Add({
	kind = "figure",
	id = "daelin-proudmoore",
	title = "Daelin Proudmoore",
	aliases = { "Daelin", "Admiral Proudmoore" },
	subtitle = "Grand Admiral of Kul Tiras",
	tier = "A",
	region = "durotar",
	allegiance = "Kul Tiras · House Proudmoore",
	unlock = {
		{ type = "read" },
		{ type = "quest", id = 784 },
		{ type = "quest", id = 830 },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Daelin Proudmoore was the Lord Admiral of {link:kul-tiras}Kul Tiras{/link} and the father of {link:jaina-proudmoore}Jaina Proudmoore{/link}. In the {link:second-war}Second War{/link} his fleets ruled the seas for the {link:alliance}Alliance{/link}, and he became one of the great heroes of humankind. He never forgave the orcs for that war. When he learned that they had settled on the shores of {link:kalimdor}Kalimdor{/link}, he came with an armada to destroy them, and he died in the attempt.]=],
		},
		{
			title = "Significance",
			text = [=[Daelin's war was the first great threat to the young nation of {link:durotar}Durotar{/link}. His death drew a line between father and daughter, and between two ways of seeing the orcs: as a people who could change, or as monsters who never would. His men still hold {link:tiragarde-keep}Tiragarde Keep{/link} in his name.]=],
		},
		{
			title = "The Admiral of the Alliance",
			text = [=[{link:kul-tiras}Kul Tiras{/link} was a kingdom of sailors, and the house of Proudmoore led its fleets. When the {link:horde}Horde{/link} marched north after the {link:first-war}First War{/link}, Daelin brought his navy into the {link:alliance}Alliance{/link} of {link:lordaeron}Lordaeron{/link}. His ships fought the orcish fleets on the open sea and carried the armies of the Alliance from shore to shore. Kul Tiras paid dearly in ships and men. Daelin remembered that price for the rest of his life.]=],
		},
		{
			title = "The Armada",
			text = [=[After the {link:third-war}Third War{/link}, his daughter {link:jaina-proudmoore}Jaina{/link} led the survivors of {link:lordaeron}Lordaeron{/link} west to {link:kalimdor}Kalimdor{/link} and built the city of {link:theramore-isle}Theramore{/link}. There she made peace with {link:thrall}Thrall{/link}. Daelin would not accept it. He sailed to Kalimdor with a great fleet, raised {link:tiragarde-keep}Tiragarde Keep{/link} on the coast of {link:durotar}Durotar{/link}, and made war on the orcs and on the trolls of the {link:echo-isles}Echo Isles{/link}. The {link:horde}Horde{/link} answered. Its warriors broke the keep, and at last they carried the fight to the walls of Theramore itself. Jaina stood aside. In the fighting, the admiral was slain.]=],
		},
		{
			title = "Deeds",
			text = [=[• He commanded the navy of {link:kul-tiras}Kul Tiras{/link} in the {link:second-war}Second War{/link}.
• He raised {link:tiragarde-keep}Tiragarde Keep{/link} on the shores of {link:durotar}Durotar{/link}.
• He made war on the {link:horde}Horde{/link} in defiance of his daughter's peace.
• He left orders for a war that would continue after his death.]=],
		},
		{
			title = "Unrecorded",
			text = [=[Little is written here of Daelin's life before the wars. This entry records only what the histories and his own orders reveal.]=],
		},
	},
	chapters = {
		{
			key = "the-admiral-s-orders",
			title = "The Admiral's Orders",
			hint = "Read the sealed orders kept at Tiragarde Keep.",
			unlock = {
				{ type = "quest", id = 830 },
				{ type = "quest", id = 831 },
			},
			text = [=[Among the belongings of {link:lieutenant-benedict}Lieutenant Benedict{/link} lay an aged envelope bearing the admiral's seal. It held orders written before Daelin ever left {link:kul-tiras}Kul Tiras{/link}. They showed that he had laid his plans well, and that more of his men were meant to follow the first fleet to {link:durotar}Durotar{/link}. The orcs of {link:razor-hill}Razor Hill{/link} read in it a simple warning: the admiral was dead, but his war was not.]=],
		},
	},
